package com.example.legacyassistant.impact;
import com.example.legacyassistant.jobs.*;
import com.example.legacyassistant.analysis.AnalysisException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import java.io.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties="analysis.jobs.enabled=false") @Transactional
class ChangeImpactIntegrationTest {
 @Autowired ChangeImpactService service;@Autowired JobStore jobs;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper json;@Autowired ImpactExport export;
 @org.springframework.test.context.bean.override.mockito.MockitoBean com.example.legacyassistant.analysis.AnalysisClient client;
 UUID requirement(){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO app.requirement(id,title,description) VALUES (?,'Impact baseline','Synthetic conditions')",id);ObjectNode a=json.createObjectNode().put("requirementId",id.toString());for(String key:List.of("confirmedConditions","ambiguousExpressions","missingConditions","relatedBusinessRules","relatedApis","clarificationQuestions","evidence"))a.putArray(key);jdbc.update("INSERT INTO app.requirement_analysis(requirement_id,result_json) VALUES (?,?::jsonb)",id,a.toString());return id;}
 ObjectNode create(){UUID id=requirement();return service.create(id,service.baseline(id).path("revision").asText(),"Proposal","Synthetic proposed change");}
 UUID id(JsonNode n,String field){return UUID.fromString(n.path(field).asText());}
 ObjectNode output(ObjectNode impact){ObjectNode r=json.createObjectNode().put("impactId",impact.path("impactId").asText()).put("baselineRevision",impact.path("baselineRevision").asText()).put("graphStatus","AVAILABLE").put("policyHash",impact.at("/baselineSnapshot/currentPolicyHash").asText()).put("modelVersion","fake-provider");for(String key:List.of("conditionChanges","affectedApis","affectedTestCases","newTestSuggestions","evidenceRefs","graphPaths"))r.putArray(key);return r;}
 ObjectNode completed(ObjectNode impact){ObjectNode job=jobs.createImpact(id(impact,"impactId"));var claimed=jobs.claim("test-worker").orElseThrow();assertTrue(jobs.complete(id(job,"jobId"),id(claimed,"executionToken"),output(impact)));return service.result(id(impact,"impactId"));}
 ObjectNode review(ObjectNode result){ObjectNode r=json.createObjectNode().put("analysisId",result.path("analysisId").asText()).put("expectedRevision",0).put("reviewer","synthetic reviewer").put("status","REVIEWED");for(String section:List.of("conditionChanges","affectedApis","affectedTestCases"))r.set(section,result.path(section));return r;}
 @Test void snapshotIsStableAndSeparate(){var p=create();var baseline=service.baseline(id(p,"baselineRequirementId"));assertEquals(p.path("baselineRevision"),baseline.path("revision"));assertTrue(p.path("baselineSnapshot").has("policyRegistry"));assertEquals(15,p.at("/baselineSnapshot/policyRegistry/plans").size());assertEquals("Synthetic conditions",jdbc.queryForObject("SELECT description FROM app.requirement WHERE id=?",String.class,id(p,"baselineRequirementId")));}
 @Test void wrongRevisionRejected(){UUID id=requirement();var e=assertThrows(AnalysisException.class,()->service.create(id,"wrong","Proposal","Change"));assertEquals("BASELINE_REVISION_MISMATCH",e.code());}
 @Test void missingBaselineRejected(){assertThrows(RuntimeException.class,()->service.baseline(UUID.randomUUID()));}
 @Test void duplicateJobsReuseIdentityAndNormalJobsSeparate(){var p=create();var one=jobs.createImpact(id(p,"impactId"));assertEquals(one.path("jobId"),jobs.createImpact(id(p,"impactId")).path("jobId"));assertEquals("CHANGE_IMPACT_ANALYSIS",one.path("jobType").asText());var regular=jobs.create(id(p,"baselineRequirementId"));assertEquals(1,jobs.list(id(p,"baselineRequirementId")).size());assertNotEquals(one.path("jobId"),regular.path("jobId"));}
 @Test void completionStoresImpactNotRequirementAnalysis(){var p=create();var r=completed(p);assertEquals(p.path("impactId"),r.path("impactId"));assertFalse(r.path("baselineStale").asBoolean());String original=jdbc.queryForObject("SELECT result_json::text FROM app.requirement_analysis WHERE requirement_id=?",String.class,id(p,"baselineRequirementId"));assertFalse(original.contains("impactId"));}
 @Test void reviewRoundTripAndRevisionGuard(){var p=create();var r=completed(p);var input=review(r);var saved=service.review(id(p,"impactId"),input);assertEquals(1,saved.path("reviewRevision").asInt());assertFalse(saved.path("businessPolicyApproved").asBoolean());assertEquals(1,service.reviews(id(p,"impactId")).size());assertEquals("REVIEW_REVISION_MISMATCH",assertThrows(AnalysisException.class,()->service.review(id(p,"impactId"),input)).code());}
 @Test void staleAnalysisReviewRejected(){var p=create();var r=completed(p);var input=review(r);input.put("analysisId",UUID.randomUUID().toString());assertEquals("ANALYSIS_REVISION_MISMATCH",assertThrows(AnalysisException.class,()->service.review(id(p,"impactId"),input)).code());}
 @Test void sourceChangeDoesNotMutateSnapshotAndBlocksReview(){var p=create();var r=completed(p);jdbc.update("UPDATE app.requirement SET description='Changed baseline' WHERE id=?",id(p,"baselineRequirementId"));assertTrue(service.result(id(p,"impactId")).path("baselineStale").asBoolean());assertEquals("Synthetic conditions",service.get(id(p,"impactId")).at("/baselineSnapshot/requirement/description").asText());assertEquals("BASELINE_STALE",assertThrows(AnalysisException.class,()->service.review(id(p,"impactId"),review(r))).code());}
 @Test void failedReanalysisKeepsGoodResult(){var p=create();var first=completed(p);var next=jobs.createImpact(id(p,"impactId"));var claim=jobs.claim("second").orElseThrow();jobs.fail(id(next,"jobId"),id(claim,"executionToken"),"TIMED_OUT","LLM_TIMEOUT");assertEquals(first.path("analysisId"),service.result(id(p,"impactId")).path("analysisId"));}
 @Test void restartRecoveryAndFencing(){var p=create();var next=jobs.createImpact(id(p,"impactId"));var claim=jobs.claim("dead").orElseThrow();jdbc.update("UPDATE app.analysis_job SET lease_expires_at=clock_timestamp()-interval '1 second' WHERE job_id=?",id(next,"jobId"));assertEquals(1,jobs.recover());assertFalse(jobs.complete(id(next,"jobId"),id(claim,"executionToken"),output(p)));assertEquals("FAILED",jobs.get(id(next,"jobId")).path("status").asText());}
 @Test void excelSevenSheetsNoFormula()throws Exception{var p=create();completed(p);try(var book=new XSSFWorkbook(new ByteArrayInputStream(export.export(id(p,"impactId"))))){assertEquals(7,book.getNumberOfSheets());for(var sheet:book)for(var row:sheet)for(var cell:row)assertNotEquals(org.apache.poi.ss.usermodel.CellType.FORMULA,cell.getCellType());}}
 @Test void sourceTablesAppendOnlyAndNoGroundTruthPrivileges(){assertFalse(jdbc.queryForObject("SELECT has_schema_privilege(current_user,'evaluation','USAGE')",Boolean.class));for(String table:List.of("change_impact","change_impact_analysis","change_impact_review"))assertFalse(jdbc.queryForObject("SELECT has_table_privilege(current_user,?,'UPDATE')",Boolean.class,"app."+table));}
 @Test void unchangedBaselineReanalysisReusesModelSnapshot(){var p=create();completed(p);org.mockito.Mockito.when(client.impact(org.mockito.ArgumentMatchers.any())).thenAnswer(call->{JsonNode request=call.getArgument(0);assertTrue(request.has("cachedModelChanges"));assertTrue(request.has("cachedAnalysisId"));return output(p);});assertEquals(p.path("impactId"),service.analyze(id(p,"impactId")).path("impactId"));}
 @Test void invalidStructuredResponseIsRejected(){var p=create();org.mockito.Mockito.when(client.impact(org.mockito.ArgumentMatchers.any())).thenReturn(json.createObjectNode());assertEquals("INVALID_ANALYSIS_OUTPUT",assertThrows(AnalysisException.class,()->service.analyze(id(p,"impactId"))).code());}
 @Test void reviewCannotForgeGraphApiId(){var p=create();var job=jobs.createImpact(id(p,"impactId"));var claimed=jobs.claim("test").orElseThrow();var output=output(p);output.withArray("affectedApis").addObject().put("apiId","actual").put("status","POTENTIALLY_AFFECTED");jobs.complete(id(job,"jobId"),id(claimed,"executionToken"),output);var input=review(service.result(id(p,"impactId")));((ObjectNode)input.path("affectedApis").get(0)).put("apiId","invented");assertEquals("REVIEW_INVALID",assertThrows(AnalysisException.class,()->service.review(id(p,"impactId"),input)).code());}
 @Test void oversizedProposalRejected(){UUID id=requirement();assertEquals("IMPACT_INPUT_INVALID",assertThrows(AnalysisException.class,()->service.create(id,service.baseline(id).path("revision").asText(),"x","x".repeat(1900))).code());}
}
